import pickle
import time

class SessionCache:
    def __init__(self, max_size=10000):
        self.cache = {}
        self.max_size = max_size
        self.access_times = {}

    def set(self, session_id, session_data):
        """Store session data by ID. session_data can be any Python object."""
        if len(self.cache) >= self.max_size:
            # LRU eviction
            oldest_id = min(self.access_times, key=self.access_times.get)
            del self.cache[oldest_id]
            del self.access_times[oldest_id]

        self.cache[session_id] = session_data
        self.access_times[session_id] = time.time()

    def get(self, session_id):
        """Retrieve session data by ID. Returns the object directly."""
        if session_id in self.cache:
            self.access_times[session_id] = time.time()
            return self.cache[session_id]
        return None

    def delete(self, session_id):
        if session_id in self.cache:
            del self.cache[session_id]
            del self.access_times[session_id]

# Usage example
cache = SessionCache()
user_session = {'user_id': 123, 'username': 'alice', 'is_admin': True, 'auth_token': 'secret_token_xyz'}
cache.set('sess_abc123', user_session)
retrieved = cache.get('sess_abc123')
print(retrieved)
